PORT=4199 node server.js > /tmp/claude/server.log 2>&1 &
sleep 1
node - <<'EOF'
const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage();
  await p.goto('http://127.0.0.1:4199/');
  await p.evaluate(() => document.fonts.ready);
  const info = await p.evaluate(async () => {
    const out = {};
    out.check700 = document.fonts.check("700 16px 'Acme Sans'");
    out.faces = [...document.fonts].map(f => ({family:f.family, weight:f.weight, style:f.style, status:f.status}));
    const measure = (weight) => {
      const s = document.createElement('span');
      s.style.cssText = `position:absolute;visibility:hidden;white-space:nowrap;font-family:'Acme Sans';font-size:100px;font-weight:${weight}`;
      s.textContent = 'Small things that make a desk feel like yours';
      document.body.appendChild(s);
      const w = s.getBoundingClientRect().width;
      s.remove();
      return w;
    };
    out.widths = {};
    for (const w of [100,300,400,500,600,700,800,900]) out.widths[w] = measure(w);
    return out;
  });
  console.log(JSON.stringify(info, null, 2));
  await b.close();
})();
EOF

